## Instructions:
1. READ server.js thoroughly (it's 5,282 lines). Read it in chunks of 500-600 lines.
2. For each route group, find the exact route handler code in server.js
3. Extract it into the appropriate route file with proper imports
4. Make sure ALL helper functions used in routes are either:
   - Imported from the lib files already created
   - Or inlined within the route file if they're tightly coupled to that domain
5. Some routes have inline helper functions (like `loadChatHistory`, `saveHistory`, `buildAiSystemPrompt`, `runClaudeSync`, `waitForApproval`, `buildScheduledPrompt`, `startScheduleJob`, `recordLearning`, etc.) — these should be inlined at the top of the relevant route file

## After creating all route files, create the new slim server.js:

```js
'use strict';
const path = require('path');
const fs = require('fs');
const express = require('express');
const db = require('./db');
const backup = require('./backup');

// Middleware
const corsMiddleware = require('./middleware/cors');
const localOnlyMiddleware = require('./middleware/localOnly');
const securityMiddleware = require('./middleware/security');

// Routes
const configRoutes = require('./routes/config');
// ... all other routes

const app = express();

// ── Middleware ─────────────────────────────────────────────────────────────
app.use(corsMiddleware);
app.use(localOnlyMiddleware);
app.use(securityMiddleware);
app.use(express.json({ limit: '2mb' }));

// ── Static files ───────────────────────────────────────────────────────────
const distPath = path.join(__dirname, '..', 'public-dist');
const legacyPath = path.join(__dirname, '..', 'public');
const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
app.use(express.static(staticPath));

// ── API Routes ──────────────────────────────────────────────────────────────
app.use('/api', configRoutes);
// ... mount all routes

// ── SPA Fallback ────────────────────────────────────────────────────────────
app.get(/^(?!\/api).*/, (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

// ── Global Error Handler ────────────────────────────────────────────────────
app.use((err, req, res, next) => {
  console.error('[server error]', err);
  if (!res.headersSent) res.status(500).json({ error: err.message || 'Internal server error' });
});

// ── Startup ────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3847;
app.listen(PORT, () => {
  console.log(`Polyglot running at http://localhost:${PORT}`);
  // Initialize DB, backup, schedules
  try { db.getDb(); console.log('[db] SQLite initialized'); } catch (e) { console.error('[db] init failed', e.message); }
  // ... backup.startBackupService(), bootSchedules(), etc.
});

module.exports = app;
```

## Very important notes:
- Keep ALL existing route logic exactly as-is — don't refactor the handlers themselves, just move them
- The `snapshotAgent` function, `loadGlobalSettings`, `loadConfig`, `saveConfig` functions that are used in routes — inline them or import from db
- The `RULE_TEMPLATES` constant — put it in `routes/rules.js` (it's only used there)
- For schedules route, the `bootSchedules()` function that starts cron jobs at startup — export it from routes/schedules.js and call it in server.js startup
- The `HOME` and `CLAUDE_DIR` constants are used in many routes — define them in each route file that needs them using `os.homedir()` etc.
- The `loadConfig` wrapper function (wraps db.loadConfig with defaults) — duplicate it in each route file that needs it OR create a `src/lib/config.js` helper that exports it

Start by reading server.js from beginning to end in chunks. Then create the files. Take your time — correctness matters more than speed.

