282	      tools: data.tools || '',
283	      body: body.trim(),
284	      raw: content,
285	      updatedAt: stats.mtime.toISOString(),
286	    };
287	    _agentCacheFull.set(filePath, { mtimeMs: stats.mtimeMs, parsed });
