294	// Meta-only parse: reads just enough to extract frontmatter + body line count.
295	// Used by list endpoints so we never ship full bodies for a 30-item list.
296	function parseAgentMeta(filePath) {
297	  try {
298	    const stats = fs.statSync(filePath);
299	    const hit = _agentCacheMeta.get(filePath);
300	    if (hit && hit.mtimeMs === stats.mtimeMs) return hit.meta;
301	
302	    // Read until we've consumed the second '---' line; cheaper than reading the
303	    // whole body only to throw it away. For files without frontmatter, fall
304	    // back to a full read via parseAgent (rare).
305	    const fd = fs.openSync(filePath, 'r');
306	    const buf = Buffer.alloc(64 * 1024);
307	    let collected = '';
308	    let bytesRead = 0;
309	    let pos = 0;
310	    let frontmatterEnd = -1;
311	    const FM_RE = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/;
312	    try {
313	      while (frontmatterEnd < 0) {
314	        const n = fs.readSync(fd, buf, 0, buf.length, pos);
315	        if (n === 0) break;
316	        collected += buf.slice(0, n).toString('utf-8');
317	        bytesRead += n;
318	        pos += n;
319	        const m = collected.match(FM_RE);
320	        if (m) frontmatterEnd = m[0].length;
321	        if (bytesRead > 256 * 1024 && frontmatterEnd < 0) break; // safety cap
322	      }
323	    } finally {
324	      fs.closeSync(fd);
325	    }
326	
327	    let data = {};
328	    let body = '';
329	    if (frontmatterEnd > 0) {
330	      const parsed = matter(collected.slice(0, frontmatterEnd + 1024)); // buffer margin
331	      data = parsed.data || {};
332	      // body is whatever follows the frontmatter — but we want LINE COUNT, not content.
333	      // A full mtime-based stat would be another syscall; estimate from file size instead.
334	    } else {
335	      // Fallback: full parse, rare case
336	      const full = parseAgent(filePath);
337	      if (!full) return null;
338	      return {
339	        filename: full.filename,
340	        path: full.path,
341	        frontmatter: full.frontmatter,
342	        name: full.name,
343	        description: full.description,
344	        model: full.model,
345	        tools: full.tools,
346	        bodyLines: full.body.split('\n').length,
347	        bodyChars: full.body.length,
348	        updatedAt: full.updatedAt,
349	      };
350	    }
351	
352	    // Compute body size cheaply from disk via stat + frontmatter length
353	    const totalSize = stats.size;
354	    const bodyChars = Math.max(0, totalSize - frontmatterEnd);
355	
356	    const meta = {
357	      filename: path.basename(filePath, '.md'),
358	      path: filePath,
359	      frontmatter: data,
360	      name: data.name || path.basename(filePath, '.md'),
361	      description: data.description || '',
362	      model: data.model || '',
363	      tools: data.tools || '',
364	      bodyLines: null, // deferred — callers that need line count use parseAgent
365	      bodyChars,
366	      updatedAt: stats.mtime.toISOString(),
367	    };
368	    _agentCacheMeta.set(filePath, { mtimeMs: stats.mtimeMs, meta });
369	    return meta;
