535	function discoverProjects(dirs) {
536	  const projects = [];
537	  for (const dir of dirs) {
538	    const resolved = dir.replace(/^~/, HOME);
539	    if (!fs.existsSync(resolved)) continue;
540	    try {
541	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
542	      for (const entry of entries) {
543	        if (!entry.isDirectory()) continue;
544	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
545	        const projectPath = path.join(resolved, entry.name);
546	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
547	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
548	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
549	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
550	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
551	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
552	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
553	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
554	          projects.push({
555	            id: Buffer.from(projectPath).toString('base64url'),
556	            name: entry.name,
557	            path: projectPath,
558	            displayPath: projectPath.replace(HOME, '~'),
559	            hasClaudeDir,
560	            hasClaudeMd,
561	            agentCount: agents.length,
562	            commandCount: commands.length,
563	            ruleCount: rules.length,
564	            agents,
565	            commands: commands.map(c => c.name),
566	            rules: rules.map(r => r.name),
567	          });
568	        }
569	      }
570	    } catch {}
571	  }
572	  return projects;
573	}
