759	// GET /api/agents/:name/health?scope=global
760	// GET /api/agents/:name/health?scope=project&projectId=xxx
761	// Accepts `content` via querystring-pairing with POST for live preview while editing.
762	app.post('/api/agents/:name/health', validateName, (req, res) => {
763	  const { scope, projectId, content } = req.body || {};
764	  let filePath = null;
765	  let raw = typeof content === 'string' ? content : null;
766	
767	  // If no live content provided, read from disk
768	  if (!raw) {
769	    if (scope === 'project' && projectId) {
770	      const projects = discoverProjects(loadConfig().projectDirs);
771	      const proj = projects.find(p => p.id === projectId);
772	      if (!proj) return res.status(404).json({ error: 'Project not found' });
773	      filePath = path.join(proj.path, '.claude', 'agents', req.params.name + '.md');
774	    } else {
775	      filePath = path.join(CLAUDE_DIR, 'agents', req.params.name + '.md');
776	    }
777	    if (!fs.existsSync(filePath)) return res.status(404).json({ error: 'Agent not found' });
778	    raw = fs.readFileSync(filePath, 'utf-8');
779	  }
780	
781	  try {
782	    const { checkBudget } = require('./compactor/budget');
783	    const check = checkBudget({ agentId: req.params.name, content: raw });
784	    const linePct = check.actual.lines / Math.max(1, check.budget.lines);
785	    const charPct = check.actual.chars / Math.max(1, check.budget.chars);
786	    const usage = Math.max(linePct, charPct);
787	
788	    // Token estimate (same heuristic used elsewhere: ~4 chars/token)
789	    const estimatedTokens = Math.ceil(raw.length / 4);
790	    const sizeKb = (raw.length / 1024);
791	
792	    // Derive status + human suggestion
793	    let status = 'healthy';
794	    let suggestion = null;
795	    if (check.violations.length > 0) {
796	      status = 'over';
797	      suggestion = `Agent is ${Math.round(usage * 100)}% of budget — consider compacting or splitting into sub-agents.`;
798	    } else if (check.warnings.length > 0) {
799	      status = 'warning';
800	      suggestion = `Approaching budget limit (${Math.round(usage * 100)}%). Trim verbose sections before it blocks saves.`;
801	    } else if (usage < 0.2) {
802	      status = 'sparse';
803	      suggestion = `Only ${Math.round(usage * 100)}% of budget used. Consider adding more detail to improve agent quality.`;
804	    } else {
805	      status = 'healthy';
806	      suggestion = `Agent is well-optimized at ${Math.round(usage * 100)}% of budget.`;
807	    }
808	
809	    res.json({
810	      status,
811	      suggestion,
812	      usage,
813	      actual: check.actual,
814	      budget: check.budget,
815	      violations: check.violations,
816	      warnings: check.warnings,
817	      estimatedTokens,
818	      sizeKb: Math.round(sizeKb * 100) / 100,
819	      rawChars: raw.length,
820	    });
821	  } catch (err) {
822	    res.status(500).json({ error: err.message || 'Health check failed' });
823	  }
824	});
