1060	      const linePct = check.actual.lines / Math.max(1, check.budget.lines);
1061	      const charPct = check.actual.chars / Math.max(1, check.budget.chars);
1062	      const usage = Math.max(linePct, charPct);
1063	      let status = 'healthy';
1064	      if (check.violations.length > 0) status = 'over';
1065	      else if (check.warnings.length > 0) status = 'warning';
1066	      else if (usage < 0.2) status = 'sparse';
1067	      const estimatedTokens = Math.ceil(agent.raw.length / 4);
1068	      return {
1069	        status,
1070	        usage,
1071	        actual: check.actual,
1072	        budget: check.budget,
1073	        estimatedTokens,
1074	        sizeKb: Math.round((agent.raw.length / 1024) * 100) / 100,
1075	      };
1076	    } catch (err) {
