1098	        departmentLabel: deptInfo?.label || null,
1099	        departmentColor: deptInfo?.color || null,
1100	        reportsTo: rec.reportsTo || null,
1101	        isLeader: Boolean(deptInfo && deptInfo.head === agent.filename),
