2033	// Topological sort helper
2034	function topoSort(nodes, edges) {
2035	  const inDegree = {};
2036	  const adj = {};
2037	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
2038	  for (const e of edges) {
2039	    adj[e.source].push(e.target);
2040	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
2041	  }
2042	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
2043	  const order = [];
2044	  while (queue.length) {
2045	    const id = queue.shift();
2046	    order.push(id);
2047	    for (const next of adj[id]) {
2048	      inDegree[next]--;
2049	      if (inDegree[next] === 0) queue.push(next);
2050	    }
2051	  }
2052	  return order;
2053	}
