2055	// Level-based grouping for parallel execution
2056	function topoLevels(nodes, edges) {
2057	  const inDegree = {};
2058	  const adj = {};
2059	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
2060	  for (const e of edges) {
2061	    adj[e.source] = adj[e.source] || [];
2062	    adj[e.source].push(e.target);
2063	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
2064	  }
2065	  const levels = [];
2066	  let queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
2067	  while (queue.length) {
2068	    levels.push([...queue]);
2069	    const nextQueue = [];
2070	    for (const id of queue) {
2071	      for (const next of (adj[id] || [])) {
2072	        inDegree[next]--;
2073	        if (inDegree[next] === 0) nextQueue.push(next);
2074	      }
2075	    }
2076	    queue = nextQueue;
2077	  }
2078	  return levels;
2079	}
