2742	function computeLineDiff(before, after) {
2743	  const oldLines = (before || '').split('\n');
2744	  const newLines = (after || '').split('\n');
2745	  const hunks = [];
2746	  const maxLen = Math.max(oldLines.length, newLines.length);
2747	  let i = 0;
2748	  while (i < maxLen) {
2749	    // Skip identical lines
2750	    if (i < oldLines.length && i < newLines.length && oldLines[i] === newLines[i]) { i++; continue; }
2751	    // Start of a changed region
2752	    const hunkStart = i;
2753	    const removed = [];
2754	    const added = [];
2755	    // Collect contiguous changed lines (simple sequential diff)
2756	    while (i < maxLen && !(i < oldLines.length && i < newLines.length && oldLines[i] === newLines[i])) {
2757	      if (i < oldLines.length && (i >= newLines.length || oldLines[i] !== newLines[i])) {
2758	        removed.push(oldLines[i]);
2759	      }
2760	      if (i < newLines.length && (i >= oldLines.length || oldLines[i] !== newLines[i])) {
2761	        added.push(newLines[i]);
2762	      }
2763	      i++;
2764	    }
2765	    if (removed.length || added.length) {
2766	      hunks.push({ line: hunkStart + 1, removed, added });
2767	    }
2768	  }
2769	  return hunks;
2770	}
