4835	// Record a learning event (called after every agent run)
4836	function recordLearning(agentName, taskType, outcome) {
4837	  const db = loadAgentLearning();
4838	
4839	  // Initialize agent profile if missing
4840	  if (!db.agents[agentName]) {
4841	    db.agents[agentName] = {
4842	      totalRuns: 0, successRuns: 0, failedRuns: 0,
4843	      avgDuration: 0, avgTokens: 0, avgCost: 0,
4844	      taskTypes: {}, // per-task-type stats
4845	      streak: 0, bestStreak: 0,
4846	      firstSeen: new Date().toISOString(),
4847	      lastSeen: null,
4848	    };
4849	  }
4850	  const agent = db.agents[agentName];
4851	  agent.totalRuns++;
4852	  agent.lastSeen = new Date().toISOString();
4853	
4854	  if (outcome.success) {
4855	    agent.successRuns++;
4856	    agent.streak = Math.max(0, agent.streak) + 1;
4857	    agent.bestStreak = Math.max(agent.bestStreak, agent.streak);
4858	  } else {
4859	    agent.failedRuns++;
4860	    agent.streak = 0;
4861	  }
4862	
4863	  // Rolling averages (exponential moving average, alpha=0.1)
4864	  const alpha = 0.1;
4865	  agent.avgDuration = agent.avgDuration === 0 ? (outcome.duration || 0) :
4866	    agent.avgDuration * (1 - alpha) + (outcome.duration || 0) * alpha;
4867	  agent.avgTokens = agent.avgTokens === 0 ? (outcome.tokens || 0) :
4868	    agent.avgTokens * (1 - alpha) + (outcome.tokens || 0) * alpha;
4869	  agent.avgCost = agent.avgCost === 0 ? (outcome.cost || 0) :
