18	      entry = { start: now, count: 0 };
19	      rateLimitMap.set(key, entry);
20	    }
21	    entry.count++;
22	    if (entry.count > max) {
23	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
