const { Router } = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const cron = require('node-cron');
const { spawn } = require('child_process');
const { rateLimit } = require('../middleware/rateLimit');
const db = require('../db');

const router = Router();

const HOME = os.homedir();
const CLAUDE_DIR = path.join(HOME, '.claude');

const activeJobs = new Map();

function loadSchedules() { return db.loadSchedules(); }
function saveSchedules(list) { try { db.saveSchedules(list); } catch (err) { console.error('[saveSchedules] DB write failed:', err.message); throw err; } }

function genId() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }

function runClaudeSync(prompt, timeoutMs = 120000) {
  return new Promise((resolve, reject) => {
    const claudePath = process.env.CLAUDE_PATH || 'claude';
    const childEnv = { ...process.env, HOME: os.homedir() };
    delete childEnv.CLAUDECODE;
    delete childEnv.CLAUDE_CODE_ENTRYPOINT;
    delete childEnv.CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING;
    delete childEnv.CLAUDE_AGENT_SDK_VERSION;
    const proc = spawn(claudePath, ['-p'], { env: childEnv });
    let out = '', err = '';
    let killed = false;

    const timer = setTimeout(() => {
      killed = true;
      proc.kill('SIGTERM');
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
    }, timeoutMs);

    proc.stdout.on('data', d => { out += d.toString(); });
    proc.stderr.on('data', d => { err += d.toString(); });
    proc.on('close', code => {
      clearTimeout(timer);
      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
      else resolve(out.trim());
    });
    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
    proc.stdin.write(prompt, 'utf8');
    proc.stdin.end();
  });
}

function logAgentRun(entry) {
  const estimateTokens = (text) => Math.ceil((text || '').length / 4);
  const estimateCost = (i, o) => (i * 3 + o * 15) / 1_000_000;
  const inputTokens = estimateTokens(entry.prompt || '');
  const outputTokens = estimateTokens(entry.output || '');
  const run = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    agentName: entry.agentName || 'unknown',
    prompt: (entry.prompt || '').slice(0, 200),
    source: entry.source || 'unknown',
    timestamp: new Date().toISOString(),
    duration: entry.duration || 0,
    status: entry.status || 'success',
    promptChars: (entry.prompt || '').length,
    outputChars: (entry.output || '').length,
    estimatedTokens: inputTokens + outputTokens,
    estimatedCost: estimateCost(inputTokens, outputTokens),
    error: entry.error || null,
    metadata: entry.metadata || {},
  };
  try { db.insertAgentRun(run); } catch (err) { console.error('[logAgentRun] DB insert failed:', err.message); }
  return run;
}

function buildScheduledPrompt(schedule) {
  let instructions = '';
  const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
  if (fs.existsSync(globalAgentsDir)) {
    for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
      const fname = file.replace('.md', '');
      if (fname === schedule.agentName || fname.toLowerCase() === schedule.agentName.toLowerCase()) {
        instructions = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
        break;
      }
    }
  }
  if (instructions) {
    return `${instructions}\n\n---\n\n## Task:\n${schedule.prompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
  }
  return schedule.prompt;
}

function startScheduleJob(schedule) {
  if (activeJobs.has(schedule.id)) { activeJobs.get(schedule.id).stop(); activeJobs.delete(schedule.id); }
  if (!schedule.enabled || !cron.validate(schedule.cron)) return;

  const job = cron.schedule(schedule.cron, async () => {
    const startTime = Date.now();
    try {
      const prompt = buildScheduledPrompt(schedule);
      const output = await runClaudeSync(prompt, 300000);
      logAgentRun({ agentName: schedule.agentName, prompt: schedule.prompt, output, source: 'schedule', duration: Date.now() - startTime, status: 'success', metadata: { scheduleId: schedule.id } });
      const schedules = loadSchedules();
      const idx = schedules.findIndex(s => s.id === schedule.id);
      if (idx >= 0) { schedules[idx].lastRunAt = new Date().toISOString(); schedules[idx].lastRunStatus = 'success'; saveSchedules(schedules); }
    } catch (err) {
      logAgentRun({ agentName: schedule.agentName, prompt: schedule.prompt, output: '', source: 'schedule', duration: Date.now() - startTime, status: 'error', error: err.message, metadata: { scheduleId: schedule.id } });
      const schedules = loadSchedules();
      const idx = schedules.findIndex(s => s.id === schedule.id);
      if (idx >= 0) { schedules[idx].lastRunAt = new Date().toISOString(); schedules[idx].lastRunStatus = 'error'; saveSchedules(schedules); }
    }
  });
  activeJobs.set(schedule.id, job);
}

function bootSchedules() {
  try {
    const schedules = loadSchedules();
    let active = 0;
    for (const s of schedules) {
      if (s.enabled) { startScheduleJob(s); active++; }
    }
    if (active > 0) console.log(`  Schedules: ${active} active cron job(s) restored`);
  } catch {}
}

